constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor sscal(const at::Tensor &input, double alpha)
{
    // ---- 输入校验 ----
    TORCH_CHECK(input.scalar_type() == at::kHalf || input.scalar_type() == at::kFloat,
