    //   FP16 (单输入Muls+升精度): inQueueX=2*2+outQueueY=2*2+tempBufFp32*2=2*4 → 16
    int64_t bufferCoefficient = (dtypeSize == 2) ? 16 : 20;
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (maxTileElements < 1) { maxTileElements = 1; }
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // ---- EXEC_KERNEL_CMD: 所有参数必须是左值 ----
    float alpha_f = static_cast<float>(alpha);

#ifndef __CHECK_FEATURE_AT_PRECOMPILE
    EXEC_KERNEL_CMD(sscal, blockDim,
                    input, output, alpha_f,
                    formerNum, formerLength, tailLength, tileLength, dtypeSize);
#endif

    return output;
}

}  // namespace ascend_kernel
